152	        TORCH_CHECK(cu_seqlens_t.is_cuda(), "cu_seqlens must be on CUDA");
153	        TORCH_CHECK(cu_seqlens_t.dtype() == torch::kLong, "cu_seqlens must be int64");
154	        TORCH_CHECK(cu_seqlens_t.dim() == 1, "cu_seqlens must be 1D");
155	        N_val = cu_seqlens_t.numel() - 1;
156	        TORCH_CHECK(N_val > 0, "cu_seqlens must have at least 2 elements");
157	        cu_seqlens_dev = cu_seqlens_t.data_ptr<int64_t>();
158	    } else {
159	        N_val = B;
160	    }
161	
162	    // Validate state shapes: always [N, H, D, D]
163	    if (has_state_in) {
164	        auto& is = initial_state.value();
