37	    // TMA layouts for Kernel 1
38	    using TMAQKLayout = typename K1L::TMAQKLayout;
39	    using TMAGLayout = typename K1L::TMAGLayout;
40	    using TMABetaSmemLayout = typename K1L::TMABetaSmemLayout;
41	    using TMAVOLayout = typename K1L::TMAVOLayout;
42	    using TMALMLayout = typename K1L::TMALMLayout;
