121	            // FP32 state TMA descriptors
122	            auto m_initial_fp32 = make_tensor(
123	                make_gmem_ptr(static_cast<float const*>(initial_state_ptr)), state_gmem_layout);
124	            auto m_final_fp32 = make_tensor(
125	                make_gmem_ptr(static_cast<float*>(final_state_ptr)), state_gmem_layout);
126	            auto tma_load = make_tma_copy(SM90_TMA_LOAD{}, m_initial_fp32, TMAFP32StateSmemLayout{});
127	            auto tma_store = make_tma_copy(SM90_TMA_STORE{}, m_final_fp32, TMAFP32StateSmemLayout{});
128	            return cute::make_tuple(tma_load, tma_store);
129	        } else {
130	            // BF16 state TMA descriptors (or dummy for no-state)
131	            auto state_ptr_load = HasStateIn
132	                ? static_cast<BF16 const*>(initial_state_ptr)
133	                : reinterpret_cast<BF16 const*>(out_ptr);  // dummy, never used
134	            auto state_ptr_store = HasStateOut
135	                ? static_cast<BF16*>(final_state_ptr)
136	                : reinterpret_cast<BF16*>(out_ptr);  // dummy, never used
137	            auto m_init = make_tensor(make_gmem_ptr(state_ptr_load), state_gmem_layout);
138	            auto m_final = make_tensor(make_gmem_ptr(state_ptr_store), state_gmem_layout);
139	            auto tma_load = make_tma_copy(SM90_TMA_LOAD{}, m_init, TMAStateSmemLayout{});
140	            auto tma_store = make_tma_copy(SM90_TMA_STORE{}, m_final, TMAStateSmemLayout{});
141	            return cute::make_tuple(tma_load, tma_store);
142	        }
143	    };
144	    auto [tma_load_initial_state, tma_store_final_state] = make_state_tma();
145	
146	    // ===== Launch Kernel 1 (prepare) =====
147	#if BLOCK_LEVEL_K1 >= 0
148	    {
149	        constexpr int kK1Threads = 256;
150	        using SharedStorageK1T = SharedStorageK1<K1L>;
151	        int smem_size_k1 = sizeof(SharedStorageK1T);
152	
153	        auto kernel1 = _flash_kda_fwd_prepare<
154	            decltype(tma_load_q), decltype(tma_load_k),
155	            decltype(tma_load_beta),
156	            decltype(tma_load_g), decltype(tma_load_dt_bias),
157	            decltype(tma_store_ws_kd), decltype(tma_store_ws_qd), decltype(tma_store_ws_kr),
158	            decltype(tma_store_ws_gt), decltype(tma_store_ws_inv), decltype(tma_store_ws_mqk),
159	            CHUNK, D, kK1Threads, IsVarlen
160	        >;
161	
