163	
164	        if constexpr (IsVarlen) {
165	            _flash_kda_build_tile_prefix<<<1, 32, 0, stream>>>(
166	                cu_seqlens_ptr, N, CHUNK, ws_tile_prefix);
167	        }
168	
169	        dim3 grid_k1(total_tiles, H);
170	        dim3 block_k1(kK1Threads);
171	
172	        kernel1<<<grid_k1, block_k1, smem_size_k1, stream>>>(
173	            tma_load_q, tma_load_k, tma_load_beta,
174	            tma_load_g, tma_load_dt_bias,
175	            tma_store_ws_kd, tma_store_ws_qd, tma_store_ws_kr,
176	            tma_store_ws_gt, tma_store_ws_inv, tma_store_ws_mqk,
177	            scale, T_total, H, N, cu_seqlens_ptr, total_tiles,
178	            A_log_ptr, gate_scale, ws_tile_prefix
179	        );
180	    }
181	#endif
182	
183	    // ===== Launch Kernel 2 (recurrence) =====
184	#if BLOCK_LEVEL_K2 >= 0
185	    {
186	        constexpr int kK2Threads = 32 * 2 + 128;
187	        using SharedStorageK2T = SharedStorageK2<K2L, kInputStages, kOutputStages>;
188	        int smem_size_k2 = sizeof(SharedStorageK2T);
189	
190	        auto kernel2 = _flash_kda_fwd_recurrence<
191	            decltype(tma_load_v), decltype(tma_load_beta2),
192	            decltype(tma_load_ws_kd), decltype(tma_load_ws_qd), decltype(tma_load_ws_kr),
193	            decltype(tma_load_ws_gt), decltype(tma_load_ws_inv), decltype(tma_load_ws_mqk),
194	            decltype(tma_load_initial_state),
195	            decltype(tma_store_final_state),
196	            decltype(tma_store_out),
197	            CHUNK, D, kInputStages, kOutputStages, kK2Threads,
198	            HasStateIn, HasStateOut, StateFP32, IsVarlen
199	        >;
200	
201	        cudaFuncSetAttribute(kernel2, cudaFuncAttributeMaxDynamicSharedMemorySize, smem_size_k2);
202	
203	        dim3 grid_k2(N, H);
204	        dim3 block_k2(kK2Threads);
205	
206	        kernel2<<<grid_k2, block_k2, smem_size_k2, stream>>>(
