208	            tma_load_ws_kd, tma_load_ws_qd, tma_load_ws_kr,
209	            tma_load_ws_gt, tma_load_ws_inv, tma_load_ws_mqk,
210	            tma_load_initial_state,
211	            tma_store_final_state,
212	            tma_store_out,
213	            out_ptr, T_total, H, N, cu_seqlens_ptr, total_tiles
214	        );
215	    }
216	#endif
217	}
